#!/usr/bin/env python3
"""Draw a small amber spark on a paper circle. Standard library only."""

import struct
import zlib
from pathlib import Path


def pixel(x: int, y: int, size: int) -> tuple[int, int, int, int]:
    cx = (size - 1) / 2
    cy = (size - 1) / 2
    dx = x - cx
    dy = y - cy
    if dx * dx + dy * dy > (size * 0.48) ** 2:
        return (0, 0, 0, 0)
    nx = abs(dx) / size
    ny = abs(dy) / size
    spark = ny < 0.06 or nx < 0.06 or abs(nx - ny) < 0.045
    if spark and (nx * nx + ny * ny) < 0.16:
        return (180, 83, 9, 255)
    return (255, 253, 248, 255)


def png(size: int) -> bytes:
    raw = bytearray()
    for y in range(size):
        raw.append(0)
        for x in range(size):
            raw.extend(pixel(x, y, size))
    compressed = zlib.compress(bytes(raw), 9)

    def chunk(tag: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)

    return b"".join(
        [
            b"\x89PNG\r\n\x1a\n",
            chunk(b"IHDR", struct.pack(">IIBBBBB", size, size, 8, 6, 0, 0, 0)),
            chunk(b"IDAT", compressed),
            chunk(b"IEND", b""),
        ]
    )


def main() -> None:
    out = Path(__file__).resolve().parents[1] / "extension" / "public" / "icon"
    out.mkdir(parents=True, exist_ok=True)
    for size in (16, 32, 48, 128):
        (out / f"{size}.png").write_bytes(png(size))


if __name__ == "__main__":
    main()
